class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long subsequences(String word, String target) {
    long[] dp = new long[target.length() + 1];
    dp[0] = 1;
    for (int i = 0; i < word.length(); i++)
      for (int j = target.length(); j >= 1; j--)
        if (word.charAt(i) == target.charAt(j - 1)) dp[j] = (dp[j] + dp[j - 1]) % MOD;
    return dp[target.length()];
  }

  public int interleaveCharacters(String word1, String word2, String target) {
    int n = word1.length(), m = word2.length(), len = target.length();
    long[][] g = new long[n + 2][m + 2];
    for (long[] row : g) java.util.Arrays.fill(row, 1);
    for (int t = len - 1; t >= 0; t--) {
      char c = target.charAt(t);
      long[][] ng = new long[n + 2][m + 2];
      long[][] a = new long[n + 2][m + 2], b = new long[n + 2][m + 2];
      for (int i = n; i >= 0; i--) {
        for (int j = m; j >= 0; j--) {
          long av = i < n ? a[i + 1][j] : 0;
          if (i < n && word1.charAt(i) == c) av = (av + g[i + 1][j]) % MOD;
          a[i][j] = av;
          long bv = j < m ? b[i][j + 1] : 0;
          if (j < m && word2.charAt(j) == c) bv = (bv + g[i][j + 1]) % MOD;
          b[i][j] = bv;
          ng[i][j] = (av + bv) % MOD;
        }
      }
      g = ng;
    }
    long total = g[0][0] - subsequences(word1, target) - subsequences(word2, target);
    return (int) (((total % MOD) + MOD) % MOD);
  }
}
